 870     Value *RuntimeVF = getRuntimeVF(State.Builder, IdxTy, State.VF);
 871 
 872     for (unsigned Idx = 1; Idx != getNumOperands(); ++Idx) {
 873       Value *VectorStart =
 874           Builder.CreateMul(RuntimeVF, ConstantInt::get(IdxTy, Idx - 1));
 875       Value *VectorIdx = Idx == 1
 876                              ? LaneToExtract
 877                              : Builder.CreateSub(LaneToExtract, VectorStart);
 878       Value *Ext = State.VF.isScalar()
 879                        ? State.get(getOperand(Idx))
 880                        : Builder.CreateExtractElement(
 881                              State.get(getOperand(Idx)), VectorIdx);
 882       if (Res) {
 883         Value *Cmp = Builder.CreateICmpUGE(LaneToExtract, VectorStart);
 884         Res = Builder.CreateSelect(Cmp, Ext, Res);
 885       } else {
 886         Res = Ext;
 887       }
 888     }
 889     return Res;
 890   }
 891   case VPInstruction::FirstActiveLane: {
 892     if (getNumOperands() == 1) {
 893       Value *Mask = State.get(getOperand(0));
 894       return Builder.CreateCountTrailingZeroElems(Builder.getInt64Ty(), Mask,
 895                                                   true, Name);
 896     }
 897     // If there are multiple operands, create a chain of selects to pick the
 898     // first operand with an active lane and add the number of lanes of the
 899     // preceding operands.
 900     Value *RuntimeVF =
 901         getRuntimeVF(State.Builder, State.Builder.getInt64Ty(), State.VF);
 902     unsigned LastOpIdx = getNumOperands() - 1;
 903     Value *Res = nullptr;
 904     for (int Idx = LastOpIdx; Idx >= 0; --Idx) {
 905       Value *TrailingZeros = Builder.CreateCountTrailingZeroElems(
 906           Builder.getInt64Ty(), State.get(getOperand(Idx)), true, Name);
 907       Value *Current = Builder.CreateAdd(
 908           Builder.CreateMul(RuntimeVF, Builder.getInt64(Idx)), TrailingZeros);
 909       if (Res) {
 910         Value *Cmp = Builder.CreateICmpNE(TrailingZeros, RuntimeVF);
 911         Res = Builder.CreateSelect(Cmp, Current, Res);
 912       } else {
 913         Res = Current;
 914       }
 915     }
 916 
 917     return Res;
 918   }
 919   default:
 920     llvm_unreachable("Unsupported opcode for instruction");
 921   }
 922 }
