 771                                                VPTypeAnalysis &TypeInfo,
 772                                                VPBlockBase *PredVPBB,
 773                                                VPValue *Op) {
 774   using namespace VPlanPatternMatch;
 775 
 776   VPValue *Incoming, *Mask;
 777   if (!match(Op, m_VPInstruction<VPInstruction::ExtractLane>(
 778                      m_VPInstruction<VPInstruction::FirstActiveLane>(
 779                          m_VPValue(Mask)),
 780                      m_VPValue(Incoming))))
 781     return nullptr;
