1030 void VPInstruction::execute(VPTransformState &State) {
1031   assert(!State.Lane && "VPInstruction executing an Lane");
1032   IRBuilderBase::FastMathFlagGuard FMFGuard(State.Builder);
1033   assert(flagsValidForOpcode(getOpcode()) &&
1034          "Set flags not supported for the provided opcode");
1035   if (hasFastMathFlags())
1036     State.Builder.setFastMathFlags(getFastMathFlags());
1037   bool GeneratesPerFirstLaneOnly = canGenerateScalarForFirstLane() &&
1038                                    (vputils::onlyFirstLaneUsed(this) ||
1039                                     isVectorToScalar() || isSingleScalar());
1040   bool GeneratesPerAllLanes = doesGeneratePerAllLanes();
1041   if (GeneratesPerAllLanes) {
1042     for (unsigned Lane = 0, NumLanes = State.VF.getFixedValue();
1043          Lane != NumLanes; ++Lane) {
1044       Value *GeneratedValue = generatePerLane(State, VPLane(Lane));
1045       assert(GeneratedValue && "generatePerLane must produce a value");
1046       State.set(this, GeneratedValue, VPLane(Lane));
1047     }
1048     return;
1049   }
1050 
1051   Value *GeneratedValue = generate(State);
1052   if (!hasResult())
1053     return;
1054   assert(GeneratedValue && "generate must produce a value");
1055   assert((((GeneratedValue->getType()->isVectorTy() ||
1056             GeneratedValue->getType()->isStructTy()) ==
1057            !GeneratesPerFirstLaneOnly) ||
1058           State.VF.isScalar()) &&
1059          "scalar value but not only first lane defined");
1060   State.set(this, GeneratedValue,
1061             /*IsScalar*/ GeneratesPerFirstLaneOnly);
1062 }
1063 
1064 bool VPInstruction::opcodeMayReadOrWriteFromMemory() const {
1065   if (Instruction::isBinaryOp(getOpcode()) || Instruction::isCast(getOpcode()))
1066     return false;
1067   switch (getOpcode()) {
1068   case Instruction::ExtractElement:
1069   case Instruction::Freeze:
1070   case Instruction::FCmp:
1071   case Instruction::ICmp:
1072   case Instruction::Select:
1073   case VPInstruction::AnyOf:
1074   case VPInstruction::BuildStructVector:
1075   case VPInstruction::BuildVector:
1076   case VPInstruction::CalculateTripCountMinusVF:
1077   case VPInstruction::CanonicalIVIncrementForPart:
1078   case VPInstruction::ExtractLane:
1079   case VPInstruction::ExtractLastElement:
1080   case VPInstruction::ExtractPenultimateElement:
1081   case VPInstruction::FirstActiveLane:
1082   case VPInstruction::FirstOrderRecurrenceSplice:
1083   case VPInstruction::LogicalAnd:
1084   case VPInstruction::Not:
1085   case VPInstruction::PtrAdd:
1086   case VPInstruction::WideIVStep:
1087   case VPInstruction::StepVector:
1088   case VPInstruction::ReductionStartVector:
1089     return false;
1090   default:
1091     return true;
1092   }
1093 }
1094 
1095 bool VPInstruction::onlyFirstLaneUsed(const VPValue *Op) const {
1096   assert(is_contained(operands(), Op) && "Op must be an operand of the recipe");
1097   if (Instruction::isBinaryOp(getOpcode()) || Instruction::isCast(getOpcode()))
1098     return vputils::onlyFirstLaneUsed(this);
1099 
1100   switch (getOpcode()) {
1101   default:
1102     return false;
1103   case Instruction::ExtractElement:
1104     return Op == getOperand(1);
1105   case Instruction::PHI:
1106     return true;
1107   case Instruction::FCmp:
1108   case Instruction::ICmp:
1109   case Instruction::Select:
1110   case Instruction::Or:
1111   case Instruction::Freeze:
1112     // TODO: Cover additional opcodes.
1113     return vputils::onlyFirstLaneUsed(this);
1114   case VPInstruction::ActiveLaneMask:
1115   case VPInstruction::ExplicitVectorLength:
1116   case VPInstruction::CalculateTripCountMinusVF:
1117   case VPInstruction::CanonicalIVIncrementForPart:
1118   case VPInstruction::BranchOnCount:
1119   case VPInstruction::BranchOnCond:
1120   case VPInstruction::Broadcast:
1121   case VPInstruction::ReductionStartVector:
1122     return true;
1123   case VPInstruction::PtrAdd:
1124     return Op == getOperand(0) || vputils::onlyFirstLaneUsed(this);
1125   case VPInstruction::ComputeAnyOfResult:
1126   case VPInstruction::ComputeFindIVResult:
1127     return Op == getOperand(1);
1128   case VPInstruction::ExtractLane:
1129     return Op == getOperand(0);
1130   };
1131   llvm_unreachable("switch should return");
1132 }
1133 
1134 bool VPInstruction::onlyFirstPartUsed(const VPValue *Op) const {
1135   assert(is_contained(operands(), Op) && "Op must be an operand of the recipe");
1136   if (Instruction::isBinaryOp(getOpcode()))
1137     return vputils::onlyFirstPartUsed(this);
1138 
1139   switch (getOpcode()) {
1140   default:
1141     return false;
1142   case Instruction::FCmp:
1143   case Instruction::ICmp:
1144   case Instruction::Select:
1145     return vputils::onlyFirstPartUsed(this);
1146   case VPInstruction::BranchOnCount:
1147   case VPInstruction::BranchOnCond:
1148   case VPInstruction::CanonicalIVIncrementForPart:
1149     return true;
1150   };
1151   llvm_unreachable("switch should return");
1152 }
